# By-dish food cost demo: recipes written by Maya (placeholder values, to be replaced with real restaurant data)
RECIPES = {
    "Beef Pho":        {"beef_brisket_lb": 0.3, "rice_noodles_lb": 0.2, "onion_ea": 0.25},
    "Chicken Fried Rice": {"chicken_thigh_lb": 0.25, "rice_lb": 0.3, "egg_ea": 1},
    "Veggie Spring Roll": {"rice_paper_ea": 2, "carrot_lb": 0.1, "lettuce_lb": 0.1},
}
UNIT_COST = {"beef_brisket_lb": 6.5, "rice_noodles_lb": 1.8, "onion_ea": 0.6,
             "chicken_thigh_lb": 3.2, "rice_lb": 0.9, "egg_ea": 0.3,
             "rice_paper_ea": 0.25, "carrot_lb": 0.8, "lettuce_lb": 1.5}
PRICE = {"Beef Pho": 15.0, "Chicken Fried Rice": 14.0, "Veggie Spring Roll": 7.0}
SALES = {"Beef Pho": 120, "Chicken Fried Rice": 85, "Veggie Spring Roll": 60}  # units sold, sample week

def food_cost_pct(dish):
    cost = sum(UNIT_COST[i] * q for i, q in RECIPES[dish].items())
    return cost, cost / PRICE[dish] * 100

if __name__ == "__main__":
    print(f"{'Dish':22}{'Cost':>8}{'Price':>8}{'FC%':>8}{'Units':>7}")
    for d in RECIPES:
        c, p = food_cost_pct(d)
        print(f"{d:22}{c:8.2f}{PRICE[d]:8.2f}{p:7.1f}%{SALES[d]:7d}")
    total_rev = sum(PRICE[d]*SALES[d] for d in RECIPES)
    total_cost = sum(food_cost_pct(d)[0]*SALES[d] for d in RECIPES)
    print(f"Week total: revenue ${total_rev:,.2f}, food cost ${total_cost:,.2f} ({total_cost/total_rev*100:.1f}%)")
